lay: flex;\n\tbox-shadow: 0 0 36px var(--color-box-shadow);\n\tborder-radius: var(--border-radius);\n\topacity: 90%;\n\tpointer-events: none;\n}\n\n.drop-hint {\n\tmargin: auto;\n\t&__icon {\n\t\tbackground-size: 48px;\n\t\theight: 48px;\n\t\tmargin-bottom: 16px;\n\t}\n}\n\n.slide {\n\t&-enter {\n\t\ttransform: translateY(-50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(-50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\tpointer-events: none;\n\t\ttransition: $fade-transition-slow;\n\t}\n}\n"],"sourceRoot":""}]);
