\n// recommended is 48px\n// 44px is what we choose and have very good visual-to-usability ratio\n$clickable-area: 44px;\n\n// background icon size\n// also used for the scss icon font\n$icon-size: 16px;\n\n// icon padding for a $clickable-area width and a $icon-size icon\n// ( 44px - 16px ) / 2\n$icon-margin: math.div($clickable-area - $icon-size, 2);\n\n// transparency background for icons\n$icon-focus-bg: rgba(127, 127, 127, .25);\n\n// popovermenu arrow width from the triangle center\n$arrow-width: 9px;\n\n// opacities\n$opacity_disabled: .5;\n$opacity_normal: .7;\n$opacity_full: 1;\n\n// menu round background hover feedback\n// good looking on dark AND white bg\n$action-background-hover: rgba(127, 127, 127, .25);\n\n// various structure data used in the\n// `NcAppNavigation` component\n$header-height: 50px;\n$navigation-width: 300px;\n\n// mobile breakpoint\n$breakpoint-mobile: 1024px;\n\n//messages list max width\n$messages-list-max-width: 800px;\n\n//message max width\n$message-max-width: 680px;\n\n//message utils width\n$message-utils-width: 100px;\n\n//message form max height\n$message-form-max-height: 180px;\n\n$color-call-background: rgba(34, 34, 34, 0.8);\n$color-guests-avatar: #ffffff;\n$color-background-guests-avatar: #b9b9b9;\n\n\n//chat font size\n$chat-font-size: 15px;\n\n//chat line height\n$chat-line-height: 1.6em;\n\n// fade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","\n@import '../../../assets/variables';\n\n.wrapper {\n\tdisplay: flex;\n\talign-items: center;\n\tposition: absolute;\n\tbottom: 0;\n\twidth: 100%;\n\tpadding: 0 12px 8px 12px;\n\tz-index: 1;\n\n\t&--big {\n\t\tjustify-content: center;\n\t\t& .bottom-bar {\n\t\t\twidth: unset;\n\t\t}\n\t\t& .participant-name {\n\t\t\tmargin-right: 0;\n\t\t}\n\t}\n}\n\n.bottom-bar {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 8px;\n\twidth: 100%;\n\theight: 44px;\n\n\t& .media-indicators {\n\t\tdisplay: flex;\n\t}\n\n\t& .following-button {\n\t\topacity: 0.8;\n\t\tbackground-color: var(--color-background-dark);\n\n\t\t&:hover,\n\t\t&:focus {\n\t\t\topacity: 1;\n\t\t}\n\t}\n}\n\n.participant-name {\n\tcolor: white;\n\tmargin: 0 auto 0 8px;\n\tposition: relative;\n\twhite-space: nowrap;\n\toverflow: hidden;\n\ttext-overflow: ellipsis;\n\tfilter: drop-shadow(1px 1px 4px var(--color-box-shadow));\n\t&--active {\n\t\tfont-weight: bold;\n\t}\n\t&--has-shadow {\n\t\ttext-shadow: 0 0 4px rgba(0, 0, 0, .8);\n\t}\n}\n\n.status-indicator {\n\twidth: 44px;\n\theight: 44px;\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n}\n\n.iceFailedIndicator {\n\topacity: .8 !important;\n}\n\n.audioIndicator[disabled],\n.videoIndicator {\n\topacity: .7;\n}\n\n.videoIndicator {\n\t&:hover,\n\t&:focus {\n\t\topacity: 1;\n\t}\n}\n\n"],"sourceRoot":""}]);
