ade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","\n@import '../../../../../assets/variables';\n\n.message-buttons-bar {\n\tdisplay: flex;\n\tright: 14px;\n\ttop: 8px;\n\tposition: sticky;\n\tbackground-color: var(--color-main-background);\n\tborder-radius: calc(var(--default-clickable-area) / 2);\n\tbox-shadow: 0 0 4px 0 var(--color-box-shadow);\n\theight: 44px;\n\tz-index: 1;\n\n\t& h6 {\n\t\tmargin-left: auto;\n\t}\n}\n\n"],"sourceRoot":""}]);
