size: 15px;\n\n//chat line height\n$chat-line-height: 1.6em;\n\n// fade transition\n$fade-transition: all var(--animation-quick, 100ms) ease-in-out;\n$fade-transition-slow: all var(--animation-slow, 300ms) ease-in-out;\n\n.fade {\n\t&-enter {\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t}\n}\n\n.slide-down {\n\t&-enter {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-to {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave {\n\t\ttransform: translateY(0);\n\t\topacity: 1;\n\t}\n\t&-leave-to {\n\t\ttransform: translateY(50%);\n\t\topacity: 0;\n\t}\n\t&-enter-active,\n\t&-leave-active {\n\t\ttransition: $fade-transition;\n\t\t/* force top container to resize during animation */\n\t\tposition: absolute !important;\n\t}\n}\n","/**\n * @copyright Copyright (c) 2020 Joas Schilling <coding@schilljs.com>\n *\n * @author Joas Schilling <coding@schilljs.com>\n *\n * @license GNU AGPL version 3 or any later version\n *\n * This program is free software: you can redistribute it and/or modify\n * it under the terms of the GNU Affero General Public License as\n * published by the Free Software Foundation, either version 3 of the\n * License, or (at your option) any later version.\n *\n * This program is distributed in the hope that it will be useful,\n * but WITHOUT ANY WARRANTY; without even the implied warranty of\n * MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n * GNU Affero General Public License for more details.\n *\n * You should have received a copy of the GNU Affero General Public License\n * along with this program. If not, see <http://www.gnu.org/licenses/>.\n *\n */\n@use 'sass:math';\n\n@import 'variables';\n\n\n@mixin avatar-mixin($size: 32px) {\n\t.avatar-#{$size} {\n\t\tposition: sticky;\n\t\ttop: 0;\n\t\twidth: $size;\n\t\theight: $size;\n\t\tline-height: $size;\n\t\tfont-size: math.div($size, 2);\n\t\tborder-radius: 50%;\n\n\t\t&.icon {\n\t\t\tborder-radius: 50%;\n\t\t\theight: $size;\n\t\t\twidth: $size;\n\t\t\tbackground-color: var(--color-background-darker);\n\t\t}\n\n\t\t&.bot {\n\t\t\tpadding-left: 5px;\n\t\t\tline-height: $size;\n\t\t\tborder-radius: 50%;\n\t\t\tbackground-color: var(--color-background-darker);\n\t\t}\n\n\t\t&.guest {\n\t\t\tline-height: $size;\n\t\t\tfont-size: math.div($size, 2);\n\t\t\tcolor: $color-guests-avatar;\n\t\t\tbackground-color: $color-background-guests-avatar;\n\t\t\tpadding: 0;\n\t\t\tdisplay: block;\n\t\t\ttext-align: center;\n\t\t\tmargin-left: auto;\n\t\t\tmargin-right: auto;\n\t\t}\n\t}\n}\n","\n@import '../../assets/variables';\n@import '../../assets/avatar';\n@include avatar-mixin(64px);\n@include avatar-mixin(128px);\n\n.device-checker {\n\tpadding: 20px;\n\tbackground-color: var(--color-main-background);\n\toverflow-y: auto;\n\toverflow-x: hidden;\n\tmargin: auto;\n\t&__title {\n\t\ttext-align: center;\n\t}\n\t&__preview {\n\t\tposition: relative;\n\t\tmargin: 0 auto 12px auto;\n\t\tdisplay: flex;\n\t\talign-items: center;\n\t\tjustify-content: center;\n\t\toverflow: hidden;\n\t\tborder-radius: 12px;\n\t\theight: 263px;\n\t\tbackground-color: var(--color-loading-dark);\n\t}\n\n\t&__device-selection {\n\t\twidth: 100%;\n\t}\n\n\t&__call-preferences {\n\t\theight: $clickable-area;\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\talign-items: center;\n\t}\n\n\t&__call-buttons {\n\t\tdisplay: flex;\n\t\talign-items: center;\n\t\tjustify-content: center;\n\t\tgap: 4px;\n\t}\n}\n\n.preview {\n\t&__video {\n\t\tmax-width: 100%;\n\t\tobject-fit: contain;\n\t\tmax-height: 100%;\n\t}\n\n\t&__novideo {\n\t\tdisplay: flex;\n\t\talign-items: center;\n\t\tjustify-content: center;\n\t\toverflow: hidden;\n\t\twidth: 100%;\n\t}\n}\n\n.select-devices {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\tmargin: auto;\n}\n\n.call-button {\n\tdisplay: flex;\n\tjustify-content: center;\n\talign-items: center;\n}\n\n.checkbox {\n\tdisplay: flex;\n\tjustify-content: center;\n\tmargin: 14px;\n}\n\n:deep(.modal-container) {\n\tdisplay: flex !important;\n}\n"],"sourceRoot":""}]);
